Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_compact_reclaims_unused_space(void) {
    // Setup: Create a buffer with extra unused space
    // We'll use buffer_new_with_size to allocate a buffer larger than the string we store
    size_t initial_size = 32;
    buffer_t *buf = buffer_new_with_size(initial_size);
    TEST_ASSERT_NOT_NULL(buf);

    // Fill buffer with a short string, leaving unused space
    const char *test_str = "hello world";
    int ret = buffer_append(buf, test_str);
    TEST_ASSERT_EQUAL_INT(0, ret);

    // Confirm buffer's logical length and allocated size
    size_t logical_length = buffer_length(buf);
    size_t allocated_size = buffer_size(buf);
    TEST_ASSERT_TRUE(allocated_size > logical_length);

    // Save the original allocation size for later comparison
    size_t original_size = allocated_size;

    // Call buffer_compact to reclaim unused space
    ssize_t reclaimed = buffer_compact(buf);

    // After compaction, buffer's allocated size should match its logical length
    size_t compacted_size = buffer_size(buf);
    size_t expected_compacted_size = logical_length;

    // Assertions
    TEST_ASSERT_EQUAL_INT(original_size - expected_compacted_size, reclaimed);
    helper_assert_buffer_length(buf, logical_length);
    helper_assert_buffer_size(buf, expected_compacted_size);
    helper_assert_buffer_data_equals(buf, test_str);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_compact_reclaims_unused_space);
    return UNITY_END();
}


